import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.LX5S0jbT.js";const m=JSON.parse('{"title":"Settings Reference","description":"","frontmatter":{},"headers":[],"relativePath":"settings.md","filePath":"settings.md"}'),r={name:"settings.md"};function c(n,t,i,s,l,u){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="settings-reference" tabindex="-1">Settings Reference <a class="header-anchor" href="#settings-reference" aria-label="Permalink to &quot;Settings Reference&quot;">​</a></h1><p>This reference lists user-configurable settings, their types, defaults, and purposes. Project settings override agent-directory settings. Resource lists are combined. See <a href="./configuration.html">Configuration</a> for file locations and trust behavior.</p><p>Add <code>&quot;$schema&quot;: &quot;https://pi.dev/schemas/settings.schema.json&quot;</code> to <code>settings.json</code> for editor validation and completion.</p><h2 id="model-and-thinking" tabindex="-1">Model and thinking <a class="header-anchor" href="#model-and-thinking" aria-label="Permalink to &quot;Model and thinking&quot;">​</a></h2><p><a id="model-cycling"></a></p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>defaultProvider</code></td><td>string</td><td>Automatic</td><td>Startup AI provider.</td></tr><tr><td><code>defaultModel</code></td><td>string</td><td>Automatic</td><td>Startup model ID.</td></tr><tr><td><code>defaultThinkingLevel</code></td><td><code>&quot;off&quot; | &quot;minimal&quot; | &quot;low&quot; | &quot;medium&quot; | &quot;high&quot; | &quot;xhigh&quot; | &quot;max&quot;</code></td><td><code>&quot;medium&quot;</code></td><td>Startup thinking level.</td></tr><tr><td><code>modelThinkingLevels</code></td><td>object</td><td>None</td><td>Per-model startup thinking levels keyed by exact <code>provider/modelId</code>.</td></tr><tr><td><code>thinkingBudgets</code></td><td>object</td><td>Built-in budgets</td><td>Token budgets for <code>minimal</code>, <code>low</code>, <code>medium</code>, and <code>high</code> thinking levels.</td></tr><tr><td><code>enabledModels</code></td><td><code>string[]</code></td><td>All available models</td><td>Model patterns used for startup selection and model cycling. Uses the same format as <code>--models</code>.</td></tr><tr><td><code>hideThinkingBlock</code></td><td>boolean</td><td><code>false</code></td><td>Hide thinking blocks in the transcript.</td></tr><tr><td><code>showCacheMissNotices</code></td><td>boolean</td><td><code>false</code></td><td>Show notices for significant cache misses, successful cache warming, compaction usage, and provider recovery.</td></tr><tr><td><code>cacheWarming</code></td><td><code>&quot;off&quot; | &quot;streaming&quot; | &quot;idle&quot;</code></td><td><code>&quot;streaming&quot;</code></td><td>Keep eligible provider prompt caches warm during active runs or, with <code>&quot;idle&quot;</code>, between runs. Global setting only.</td></tr></tbody></table><p>Cache warming runs only when the model declares a cache lifetime and Pi estimates at least $0.05 in avoided cache-miss cost. Refresh usage counts toward session totals but does not enter model context. <code>/session</code> shows the next decision; extensions can override it with <code>cache_warming_decision</code>. See <a href="./models.html#prompt-cache-lifetimes">Prompt Cache Lifetimes</a>.</p><p>See <a href="./models.html">Choose a Model</a> for model selection and thinking controls.</p><h2 id="interaction" tabindex="-1">Interaction <a class="header-anchor" href="#interaction" aria-label="Permalink to &quot;Interaction&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>steeringMode</code></td><td><code>&quot;all&quot; | &quot;one-at-a-time&quot;</code></td><td><code>&quot;one-at-a-time&quot;</code></td><td>How queued steering messages are delivered.</td></tr><tr><td><code>followUpMode</code></td><td><code>&quot;all&quot; | &quot;one-at-a-time&quot;</code></td><td><code>&quot;one-at-a-time&quot;</code></td><td>How queued follow-up messages are delivered.</td></tr><tr><td><code>externalEditor</code></td><td>string</td><td><code>$VISUAL</code>, <code>$EDITOR</code>, then platform default</td><td>Command opened by the external-editor keybinding.</td></tr><tr><td><code>doubleEscapeAction</code></td><td><code>&quot;tree&quot; | &quot;fork&quot; | &quot;none&quot;</code></td><td><code>&quot;tree&quot;</code></td><td>Action for double Escape with an empty editor.</td></tr><tr><td><code>treeFilterMode</code></td><td><code>&quot;default&quot; | &quot;no-tools&quot; | &quot;user-only&quot; | &quot;labeled-only&quot; | &quot;all&quot;</code></td><td><code>&quot;default&quot;</code></td><td>Initial filter used by <code>/tree</code>.</td></tr><tr><td><code>defaultProjectTrust</code></td><td><code>&quot;ask&quot; | &quot;always&quot; | &quot;never&quot;</code></td><td><code>&quot;ask&quot;</code></td><td>Fallback project-trust behavior. <strong>Can only be set in agent-directory settings.</strong></td></tr></tbody></table><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>defaultTools</code></td><td><code>string[]</code></td><td><code>read</code>, <code>bash</code>, <code>edit</code>, <code>write</code></td><td>Tools enabled at startup. Plain names replace the defaults; <code>+name</code> adds a tool and <code>-name</code> removes one. An empty array disables all built-in tools but not extension or SDK tools.</td></tr><tr><td><code>codemode.mode</code></td><td><code>&quot;on&quot;</code> | <code>&quot;only&quot;</code></td><td><code>&quot;on&quot;</code></td><td>How the <code>codemode</code> tool presents tools while it is active. <code>on</code>: declared tools get a note on calling them from scripts appended to their description, and <code>codemode</code> lists only tools that are not declared. <code>only</code>: <code>codemode</code> lists every tool scripts can call, and active built-in and extension tools are hidden from the model, so it reaches them through <code>codemode</code>.</td></tr><tr><td><code>codemode.inlineBudget</code></td><td>number</td><td><code>3000</code></td><td>Estimated tokens (characters / 4) the <code>codemode</code> tool&#39;s description may spend on tool declarations. Tools that do not fit are left out and found with <code>searchTools()</code>. <code>0</code> lists only namespaces.</td></tr></tbody></table><p>Available built-in tools are <code>read</code>, <code>bash</code>, <code>powershell</code>, <code>edit</code>, <code>write</code>, <code>grep</code>, <code>find</code>, and <code>ls</code>. <code>defaultTools</code> can also name <code>codemode</code> and <code>tool_search</code>, which built-in extensions register inactive, and other extension tools registered inactive.</p><p>A list of only <code>+name</code> and <code>-name</code> entries changes the inherited selection instead of replacing it. For example, this enables <code>codemode</code> next to the default tools:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultTools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;+codemode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This replaces <code>bash</code> with <code>powershell</code> and enables <code>grep</code>: <code>[&quot;-bash&quot;, &quot;+powershell&quot;, &quot;+grep&quot;]</code>. Project settings apply on top of user settings: a project list with only <code>+name</code> and <code>-name</code> entries changes the user&#39;s selection, and a project list with a plain name replaces it. In one list, plain names form the selection, and <code>+name</code> and <code>-name</code> then apply in order.</p><p><code>/reload</code> enables tools newly added to <code>defaultTools</code>. It does not disable tools removed from it or re-enable unchanged tools you turned off. <code>--tools</code> with plain names, <code>--no-tools</code>, and <code>--no-builtin-tools</code> override <code>defaultTools</code>, also on reload.</p><p>CLI tool options override this setting for one invocation. <code>--tools</code> with only <code>+name</code> and <code>-name</code> entries changes the resolved <code>defaultTools</code> selection instead, for example <code>pi --tools +codemode</code>. On <code>/reload</code>, these entries apply to the reloaded setting too, so a tool removed with <code>-name</code> stays removed. See <a href="./cli.html#tools">Command Line</a>.</p><h2 id="sessions-and-context" tabindex="-1">Sessions and context <a class="header-anchor" href="#sessions-and-context" aria-label="Permalink to &quot;Sessions and context&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>sessionDir</code></td><td>string</td><td>Agent session directory</td><td>Session storage directory. Relative paths resolve from the working directory. <code>PI_CODING_AGENT_SESSION_DIR</code> and <code>--session-dir</code> override this setting.</td></tr><tr><td><code>sessionShareDestination</code></td><td><code>&quot;auto&quot; | &quot;gist&quot; | &quot;radius&quot;</code></td><td><code>&quot;auto&quot;</code></td><td>Destination used by <code>/share</code>. <code>auto</code> uses Radius when authenticated and otherwise creates a GitHub gist. <code>gist</code> always uses a gist. <code>radius</code> requires Radius authentication and never falls back to a gist.</td></tr></tbody></table><h3 id="compaction" tabindex="-1">Compaction <a class="header-anchor" href="#compaction" aria-label="Permalink to &quot;Compaction&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>compaction.enabled</code></td><td>boolean</td><td><code>true</code></td><td>Enable automatic compaction.</td></tr><tr><td><code>compaction.reserveTokens</code></td><td>number</td><td><code>16384</code></td><td>Free context tokens below which automatic compaction starts.</td></tr><tr><td><code>compaction.keepRecentTokens</code></td><td>number</td><td><code>20000</code></td><td>Recent tokens retained without summarization.</td></tr><tr><td><code>compaction.modelOverrides</code></td><td>object</td><td>None</td><td>Per-model token settings keyed by exact <code>provider/modelId</code>.</td></tr></tbody></table><p><a id="per-model-compaction-overrides"></a></p><p>Compaction token values must be non-negative safe integers. Each value resolves independently from the matching model override, then the ordinary compaction setting, then the built-in default. Project and user objects merge before model lookup.</p><p>See <a href="./compaction.html">Compaction Reference</a> for trigger, summarization, and validation behavior.</p><h3 id="branch-summaries" tabindex="-1">Branch summaries <a class="header-anchor" href="#branch-summaries" aria-label="Permalink to &quot;Branch summaries&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>branchSummary.reserveTokens</code></td><td>number</td><td><code>16384</code></td><td>Tokens reserved when summarizing branch history.</td></tr><tr><td><code>branchSummary.skipPrompt</code></td><td>boolean</td><td><code>false</code></td><td>Skip the branch-summary prompt and default to no summary.</td></tr></tbody></table><h2 id="terminal-and-display" tabindex="-1">Terminal and display <a class="header-anchor" href="#terminal-and-display" aria-label="Permalink to &quot;Terminal and display&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>theme</code></td><td>string</td><td><code>&quot;system&quot;</code></td><td>Built-in or custom theme name. <code>system</code> derives colors from the terminal theme.</td></tr><tr><td><code>quietStartup</code></td><td>boolean | <code>&quot;header&quot;</code></td><td><code>false</code></td><td><code>true</code> hides the startup header and loaded-resource listing. <code>&quot;header&quot;</code> keeps the header (version and key hints) but hides the model scope line and loaded-resource listing.</td></tr><tr><td><code>tuiMode</code></td><td><code>&quot;regular&quot; | &quot;fullscreen&quot;</code></td><td><code>&quot;fullscreen&quot;</code></td><td>Interactive terminal UI mode.</td></tr><tr><td><code>fullscreenExitOutput</code></td><td><code>&quot;transcript&quot; | &quot;resume-hint&quot;</code></td><td><code>&quot;transcript&quot;</code></td><td>Output printed when fullscreen mode exits.</td></tr><tr><td><code>fullscreenScrollbar</code></td><td><code>&quot;auto&quot; | &quot;always&quot; | &quot;hidden&quot;</code></td><td><code>&quot;auto&quot;</code></td><td>Fullscreen transcript scrollbar behavior.</td></tr><tr><td><code>fullscreenCopyOnSelect</code></td><td>boolean</td><td><code>true</code></td><td>Copy selected text automatically in fullscreen mode.</td></tr><tr><td><code>fullscreenWheelScrollLines</code></td><td><code>&quot;auto&quot;</code> | number</td><td><code>&quot;auto&quot;</code></td><td>Lines per mouse-wheel event in fullscreen mode, from 1 to 100. <code>&quot;auto&quot;</code> moves one line per event in local macOS terminals, which already accelerate wheel and trackpad input; elsewhere, and over SSH, it speeds up fast wheel spins to at most 6 lines per event. Alt+wheel moves five times as far.</td></tr><tr><td><code>editorPaddingX</code></td><td>number</td><td><code>0</code></td><td>Horizontal editor padding from 0 to 3 cells.</td></tr><tr><td><code>outputPad</code></td><td><code>0 | 1</code></td><td><code>1</code></td><td>Horizontal transcript padding for messages, tool output, <code>!</code> command output, and summary blocks.</td></tr><tr><td><code>autocompleteMaxVisible</code></td><td>number</td><td><code>5</code></td><td>Visible autocomplete entries, from 3 to 20.</td></tr><tr><td><code>showHardwareCursor</code></td><td>boolean</td><td><code>false</code></td><td>Use the terminal cursor instead of Pi&#39;s drawn cursor. Pi still positions it for input methods.</td></tr><tr><td><code>terminal.showImages</code></td><td>boolean</td><td><code>true</code></td><td>Display inline images when supported.</td></tr><tr><td><code>terminal.imageWidthCells</code></td><td>number</td><td><code>60</code></td><td>Preferred inline image width in terminal cells.</td></tr><tr><td><code>terminal.clearOnShrink</code></td><td>boolean</td><td><code>false</code></td><td>Clear empty rows when rendered content shrinks. When unset, <code>PI_CLEAR_ON_SHRINK=1</code> enables it.</td></tr><tr><td><code>terminal.showTerminalProgress</code></td><td>boolean</td><td><code>false</code></td><td>Show OSC 9;4 progress in the terminal tab.</td></tr><tr><td><code>terminal.hyperlinks</code></td><td><code>boolean | &quot;auto&quot;</code></td><td><code>&quot;auto&quot;</code></td><td>Override OSC 8 hyperlink detection.</td></tr><tr><td><code>terminal.images</code></td><td><code>&quot;kitty&quot; | &quot;iterm2&quot; | &quot;auto&quot; | false</code></td><td><code>&quot;auto&quot;</code></td><td>Override inline-image protocol detection.</td></tr><tr><td><code>terminal.trueColor</code></td><td><code>boolean | &quot;auto&quot;</code></td><td><code>&quot;auto&quot;</code></td><td>Override true-color detection.</td></tr><tr><td><code>images.autoResize</code></td><td>boolean</td><td><code>true</code></td><td>Resize images to at most 2000 by 2000 pixels before sending them to a model.</td></tr><tr><td><code>images.blockImages</code></td><td>boolean</td><td><code>false</code></td><td>Prevent images from being sent to models.</td></tr><tr><td><code>markdown.codeBlockIndent</code></td><td>string</td><td><code>&quot; &quot;</code></td><td>Prefix used to indent rendered code blocks.</td></tr><tr><td><code>markdown.mermaid</code></td><td><code>&quot;off&quot; | &quot;final&quot; | &quot;streaming&quot;</code></td><td><code>&quot;streaming&quot;</code></td><td>Mermaid rendering mode.</td></tr></tbody></table><p>See <a href="./themes.html">Themes</a> and <a href="./terminal-setup.html">Terminal Setup</a> for format and platform details.</p><h2 id="network-and-retries" tabindex="-1">Network and retries <a class="header-anchor" href="#network-and-retries" aria-label="Permalink to &quot;Network and retries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>transport</code></td><td><code>&quot;auto&quot; | &quot;sse&quot; | &quot;websocket&quot; | &quot;websocket-cached&quot;</code></td><td><code>&quot;auto&quot;</code></td><td>Preferred transport for AI providers that support multiple transports.</td></tr><tr><td><code>httpProxy</code></td><td>string</td><td>None</td><td>Proxy URL applied as <code>HTTP_PROXY</code> and <code>HTTPS_PROXY</code> for Pi-managed HTTP clients. <strong>Can only be set in agent-directory settings.</strong></td></tr><tr><td><code>httpIdleTimeoutMs</code></td><td>number | <code>&quot;disabled&quot;</code></td><td><code>300000</code></td><td>HTTP header and body idle timeout in milliseconds. Set to <code>0</code> or <code>&quot;disabled&quot;</code> to disable.</td></tr><tr><td><code>websocketConnectTimeoutMs</code></td><td>number | <code>&quot;disabled&quot;</code></td><td><code>15000</code></td><td>WebSocket connection timeout in milliseconds. Set to <code>0</code> or <code>&quot;disabled&quot;</code> to disable.</td></tr><tr><td><code>retry.enabled</code></td><td>boolean</td><td><code>true</code></td><td>Enable automatic agent-level retry for transient failures.</td></tr><tr><td><code>retry.maxRetries</code></td><td>number</td><td><code>3</code></td><td>Maximum agent-level retry attempts.</td></tr><tr><td><code>retry.baseDelayMs</code></td><td>number</td><td><code>2000</code></td><td>Initial exponential-backoff delay in milliseconds.</td></tr><tr><td><code>retry.maxAgentDelayMs</code></td><td>number</td><td><code>60000</code></td><td>Maximum agent-level retry delay in milliseconds.</td></tr><tr><td><code>retry.provider.timeoutMs</code></td><td>number</td><td><code>httpIdleTimeoutMs</code></td><td>Provider request timeout in milliseconds.</td></tr><tr><td><code>retry.provider.maxRetries</code></td><td>number</td><td><code>0</code></td><td>Provider-level retry attempts.</td></tr><tr><td><code>retry.provider.maxRetryDelayMs</code></td><td>number</td><td><code>60000</code></td><td>Maximum server-requested delay in milliseconds. Set to <code>0</code> to disable the limit.</td></tr></tbody></table><p>Keep <code>retry.provider.maxRetries</code> at <code>0</code> unless provider-level retries are required. Provider retries can delay Pi from handling quota and usage-limit errors itself.</p><h2 id="shell" tabindex="-1">Shell <a class="header-anchor" href="#shell" aria-label="Permalink to &quot;Shell&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>shellPath</code></td><td>string</td><td>Platform default</td><td>Custom shell executable path. Supports a leading <code>~</code>.</td></tr><tr><td><code>shellCommandPrefix</code></td><td>string</td><td>None</td><td>Prefix prepended to every shell command.</td></tr><tr><td><code>npmCommand</code></td><td><code>string[]</code></td><td><code>npm</code></td><td>Command and arguments used for npm package lookup and installation.</td></tr></tbody></table><p>See <a href="./shell-aliases.html">Shell aliases</a> for shell setup and <a href="./packages.html">Pi Packages</a> for package-manager behavior.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><p>Resource paths in user settings resolve from the agent directory. Paths in project settings resolve from the project <code>.pi</code> directory. Absolute paths and <code>~</code> are supported.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>packages</code></td><td>array</td><td><code>[]</code></td><td>npm, git, or local Pi package sources. See <a href="./packages.html">Pi Packages</a>.</td></tr><tr><td><code>extensions</code></td><td><code>string[]</code></td><td><code>[]</code></td><td>Extension files or directories.</td></tr><tr><td><code>skills</code></td><td><code>string[]</code></td><td><code>[]</code></td><td>Skill files or directories.</td></tr><tr><td><code>prompts</code></td><td><code>string[]</code></td><td><code>[]</code></td><td>Prompt-template files or directories.</td></tr><tr><td><code>themes</code></td><td><code>string[]</code></td><td><code>[]</code></td><td>Theme files or directories.</td></tr><tr><td><code>enableSkillCommands</code></td><td>boolean</td><td><code>true</code></td><td>Register skills as <code>/skill:name</code> commands.</td></tr></tbody></table><p>Resource arrays support glob exclusions with <code>!pattern</code>, exact inclusion with <code>+path</code>, and exact exclusion with <code>-path</code>. Pi loads resources listed in both user-level and project settings.</p><p>The built-in extensions are named <code>builtin:mcp</code>, <code>builtin:llama.cpp</code>, <code>builtin:codemode</code>, and <code>builtin:tool-search</code> in <code>extensions</code>. They load by default; <code>-builtin:mcp</code> disables one. A <code>+builtin:&lt;name&gt;</code> or <code>-builtin:&lt;name&gt;</code> entry in project settings overrides the user setting. <code>pi config</code> lists them under Built-in. <code>--no-extensions</code> disables them too, and <code>-e builtin:&lt;name&gt;</code> loads one explicitly.</p><h2 id="updates-telemetry-and-warnings" tabindex="-1">Updates, telemetry, and warnings <a class="header-anchor" href="#updates-telemetry-and-warnings" aria-label="Permalink to &quot;Updates, telemetry, and warnings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>collapseChangelog</code></td><td>boolean</td><td><code>false</code></td><td>Show a condensed changelog after an update.</td></tr><tr><td><code>enableInstallTelemetry</code></td><td>boolean</td><td><code>true</code></td><td>Enable anonymous install/update reporting and selected provider attribution headers. Does not control update checks.</td></tr><tr><td><code>enableAnalytics</code></td><td>boolean</td><td><code>false</code></td><td>Opt in to analytics data sharing. Currently used only by the experimental first-run setup.</td></tr><tr><td><code>warnings.anthropicExtraUsage</code></td><td>boolean</td><td><code>true</code></td><td>Warn when Anthropic subscription authentication may use paid extra usage.</td></tr></tbody></table>`,43)])])}const p=e(r,[["render",c]]);export{m as __pageData,p as default};
